'use strict';

const crypto=require('crypto');
const fsp=require('fs').promises;
const path=require('path');
const {ALLOWED_UNMANAGED_TOP_LEVEL,assertManagedUnmanagedDisjoint,classifyTopLevelNames}=require('./mac_skill_bundle_shared_root_contract');
const CANONICAL_MAC_SKILL_ROOT='/Users/lsb/.codex/skills';

function option(args,name){const index=args.indexOf(name);return index>=0?args[index+1]:null;}
function hash(value){return crypto.createHash('sha256').update(value).digest('hex');}
async function syncDirectory(directory){let handle;try{handle=await fsp.open(directory,'r');await handle.sync();}catch(error){if(process.platform!=='win32'||!['EISDIR','EPERM','EINVAL','EBADF'].includes(error.code))throw error;}finally{if(handle)await handle.close();}}
async function atomicJson(filePath,value,hooks={}){const directory=path.dirname(filePath);await fsp.mkdir(directory,{recursive:true});const temp=filePath+'.tmp-'+process.pid+'-'+crypto.randomBytes(4).toString('hex');let handle;try{handle=await fsp.open(temp,'wx');await handle.writeFile(Buffer.from(JSON.stringify(value,null,2)+'\n','utf8'));await handle.sync();if(hooks.onFileSync)await hooks.onFileSync(temp);await handle.close();handle=null;await fsp.rename(temp,filePath);await syncDirectory(directory);if(hooks.onDirectorySync)await hooks.onDirectorySync(directory);}catch(error){if(handle)await handle.close().catch(()=>{});await fsp.rm(temp,{force:true}).catch(()=>{});throw error;}}
async function walk(root,relative='',lstatImpl=fsp.lstat){const output=[];for(const entry of (await fsp.readdir(path.join(root,relative),{withFileTypes:true})).sort((a,b)=>a.name.localeCompare(b.name))){const child=relative?path.posix.join(relative,entry.name):entry.name;const target=path.join(root,...child.split('/'));const stats=await lstatImpl(target);if(stats.isSymbolicLink())throw new Error('skill_bundle_parity_symlink_rejected:'+child);if(stats.isDirectory())output.push(...await walk(root,child,lstatImpl));else if(stats.isFile()){const bytes=await fsp.readFile(target);output.push({relative_path:child,bytes:bytes.length,sha256:hash(bytes)});}else throw new Error('skill_bundle_parity_special_file_rejected:'+child);}return output;}
async function validateSkillRoot(input,options={}){const resolved=path.resolve(input),hasOverride=Boolean(options.expectedSkillRoot);if(options.testMode!==true&&hasOverride)throw new Error('skill_bundle_parity_root_test_override_forbidden');let expected=CANONICAL_MAC_SKILL_ROOT;if(options.testMode===true){if(process.env.NIANNIAN_SKILL_INSTALL_TEST_MODE!=='1'||!options.expectedSkillRoot)throw new Error('skill_bundle_parity_root_test_override_forbidden');expected=path.resolve(options.expectedSkillRoot);}const stats=await fsp.lstat(resolved).catch(()=>null);if(!stats||stats.isSymbolicLink()||!stats.isDirectory())throw new Error('skill_bundle_parity_root_invalid');const real=await fsp.realpath(resolved);if(resolved!==real||real!==path.resolve(expected))throw new Error('skill_bundle_parity_root_exact_path_mismatch');return real;}

async function verify(options){
  const manifestPath=path.resolve(options.manifestPath),skillRoot=path.resolve(options.skillRoot),lstatImpl=options.lstatImpl||fsp.lstat;await validateSkillRoot(skillRoot,options);const manifestBytes=await fsp.readFile(manifestPath),manifest=JSON.parse(manifestBytes);if(!['niannian_mac_skill_bundle_v1','niannian_mac_skill_bundle_v2'].includes(manifest.schema_version)||manifest.skills.length!==13||!manifest.skills.includes('prompt-skill-router'))throw new Error('skill_bundle_manifest_contract_invalid');assertManagedUnmanagedDisjoint(manifest.skills,'skill_bundle_manifest');const top=[];for(const entry of await fsp.readdir(skillRoot,{withFileTypes:true})){const target=path.join(skillRoot,entry.name);const stats=await lstatImpl(target);if(stats.isSymbolicLink())throw new Error('skill_bundle_parity_symlink_rejected:'+entry.name);if(!stats.isDirectory())throw new Error('skill_bundle_parity_special_top_level_rejected:'+entry.name);top.push(entry.name);}const classifiedTop=classifyTopLevelNames(top,manifest.skills,'skill_bundle_parity_top_level'),unmanagedTop=classifiedTop.unmanaged_top_level_entries;const expected=manifest.files.filter(item=>item.path.startsWith('skills/')).sort((a,b)=>a.path.localeCompare(b.path));const actual=[];
  for(const skill of manifest.skills){const root=path.join(skillRoot,skill);const stats=await lstatImpl(root).catch(()=>null);if(!stats||!stats.isDirectory()||stats.isSymbolicLink())throw new Error('skill_bundle_parity_skill_root_invalid:'+skill);for(const item of await walk(root,'',lstatImpl))actual.push({path:'skills/'+skill+'/'+item.relative_path,bytes:item.bytes,sha256:item.sha256});}
  actual.sort((a,b)=>a.path.localeCompare(b.path));if(actual.length!==expected.length)throw new Error('skill_bundle_parity_inventory_count_mismatch:expected='+expected.length+':actual='+actual.length);const verified=[];for(let i=0;i<expected.length;i+=1){const wanted=expected[i],found=actual[i];if(found.path!==wanted.path)throw new Error('skill_bundle_parity_inventory_mismatch:'+found.path+':expected:'+wanted.path);if(found.bytes!==wanted.bytes||found.sha256!==wanted.sha256)throw new Error('skill_bundle_parity_mismatch:'+wanted.path);verified.push({path:wanted.path,bytes:wanted.bytes,sha256:wanted.sha256,status:'verified'});}
  const receipt={schema_version:manifest.schema_version==='niannian_mac_skill_bundle_v2'?'niannian_mac_skill_bundle_parity_receipt_v2':'niannian_mac_skill_bundle_parity_receipt_v1',status:'exact_parity_verified',bundle_id:manifest.bundle_id,profile:manifest.profile||null,manifest_sha256:hash(manifestBytes),source_snapshot_sha256:manifest.source_snapshot_sha256||null,managed_skills:manifest.skills.length,managed_file_count:verified.length,allowed_unmanaged_top_level:[...ALLOWED_UNMANAGED_TOP_LEVEL],unmanaged_top_level_entries:unmanagedTop,unmanaged_preserved:true,skills:manifest.skills.length,files:verified.length,skill_root:skillRoot,verified_files:verified,extra_files:[],symlinks:[],provider_network_requested:false,provider_submit_requested:false,secrets_collected:false,real_delivery:false,verified_at:new Date().toISOString()};if(options.receiptPath){const receiptPath=path.resolve(options.receiptPath);await atomicJson(receiptPath,receipt,options.durabilityHooks||{});const readback=JSON.parse(await fsp.readFile(receiptPath,'utf8'));if(readback.manifest_sha256!==receipt.manifest_sha256||readback.source_snapshot_sha256!==receipt.source_snapshot_sha256||readback.managed_skills!==13||readback.managed_file_count!==verified.length||JSON.stringify(readback.allowed_unmanaged_top_level)!==JSON.stringify(ALLOWED_UNMANAGED_TOP_LEVEL)||JSON.stringify(readback.unmanaged_top_level_entries)!==JSON.stringify(unmanagedTop)||readback.unmanaged_preserved!==true||readback.verified_files?.length!==verified.length)throw new Error('skill_bundle_parity_receipt_readback_mismatch');}return receipt;
}
async function main(){const args=process.argv.slice(2),testMode=args.includes('--test-mode'),expectedSkillRoot=option(args,'--expected-skill-root');if((testMode&&process.env.NIANNIAN_SKILL_INSTALL_TEST_MODE!=='1')||(!testMode&&expectedSkillRoot))throw new Error('skill_bundle_parity_root_test_override_forbidden');const manifestPath=option(args,'--manifest');const skillRoot=option(args,'--skill-root');const receiptPath=option(args,'--receipt');if(!manifestPath||!skillRoot)throw new Error('usage: --manifest <json> --skill-root <dir> [--receipt <json>]');process.stdout.write(JSON.stringify(await verify({manifestPath,skillRoot,receiptPath,testMode,expectedSkillRoot}))+'\n');}
if(require.main===module)main().catch(error=>{process.stderr.write(String(error.message||error)+'\n');process.exitCode=1;});
module.exports={ALLOWED_UNMANAGED_TOP_LEVEL,validateSkillRoot,verify,walk};
